import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

const API_BASE_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const EmployeeVacationStatus = () => {
    const [requests, setRequests] = useState([]);
    const [newNotifications, setNewNotifications] = useState(0);
    const navigate = useNavigate();
    const user = JSON.parse(localStorage.getItem('user'));

    useEffect(() => {
        if (user) {
            fetchVacationRequests();
        }
    }, [user]);

    const fetchVacationRequests = async () => {
        try {
            const response = await fetch(`${API_BASE_URL}/users/${user.id}/vacation-requests`);
            const data = await response.json();
            setRequests(data);

            // Contar notificaciones no leídas
            const unread = data.filter(req =>
                req.status !== 'pending' && !req.notification_read
            ).length;
            setNewNotifications(unread);
        } catch (error) {
            console.error('Error fetching vacation requests:', error);
        }
    };

    const markAsRead = async (requestId) => {
        try {
            await fetch(`${API_BASE_URL}/users/mark-notification-read/${requestId}`, {
                method: 'PUT'
            });
            fetchVacationRequests();
        } catch (error) {
            console.error('Error marking notification as read:', error);
        }
    };


    const grouped = {};

    requests.forEach(req => {
        if (!grouped[req.request_group_id]) {
            grouped[req.request_group_id] = {
                dates: [],
                status: req.status,
                comments: req.comments,
                notification_read: req.notification_read
            };
        }
        grouped[req.request_group_id].dates.push(req.vacation_date);
    });


    return (
        <div className="flex flex-col items-center py-10 bg-gray-100 min-h-screen">
            <div className="w-full max-w-4xl bg-white shadow-lg rounded-lg p-6">
                <div className="flex justify-between items-center mb-6">
                    <h1 className="text-2xl font-bold text-gray-800">Estado de tus Solicitudes de Vacaciones</h1>
                    {newNotifications > 0 && (
                        <span className="bg-red-500 text-white rounded-full px-2 py-1 text-xs">
                            {newNotifications} nueva(s)
                        </span>
                    )}
                </div>

                {Array.isArray(requests) && requests.length === 0 && (
                    <p className="text-gray-600 text-center mb-4">No tienes solicitudes de vacaciones registradas.</p>
                )}

                <table className="w-full">
                    <thead className="bg-gray-100">
                    <tr>
                        <th className="p-3 text-left">Fecha</th>
                        <th className="p-3 text-left">Estado</th>
                        <th className="p-3 text-left">Comentarios</th>
                    </tr>
                    </thead>
                    <tbody>

                    {Object.entries(grouped).map(([groupId, group]) => {
                        const sorted = group.dates.sort();
                        const from = sorted[0];
                        const to = sorted[sorted.length - 1];
                        return (
                            <tr key={groupId}>
                                <td className="px-4 py-2 text-center">{from === to ? from : `${from} al ${to}`}</td>
                                <td className="px-4 py-2 text-center capitalize">{group.status}</td>
                                <td className="px-4 py-2 text-center">{group.comments || 'Sin comentarios'}</td>
                                <td className="px-4 py-2 text-center">{group.notification_read ? 'Leído' : 'Nuevo'}</td>
                            </tr>
                        );
                    })}

                    <tr
                        key={request.id}
                        className={`border-b ${
                            !request.notification_read && request.status !== 'pending' ? 'bg-blue-50' : ''
                        }`}
                        onClick={() => markAsRead(request.id)}
                    >
                        <td className="p-3">{new Date(request.vacation_date).toLocaleDateString()}</td>
                        <td className="p-3">
                                    <span className={`px-2 py-1 rounded-full text-xs ${
                                        request.status === 'approved' ? 'bg-green-100 text-green-800' :
                                            request.status === 'rejected' ? 'bg-red-100 text-red-800' :
                                                'bg-yellow-100 text-yellow-800'
                                    }`}>
                                        {request.status === 'approved' ? 'Aprobado' :
                                            request.status === 'rejected' ? 'Rechazado' : 'Pendiente'}
                                    </span>
                        </td>
                        <td className="p-3 text-sm text-gray-600">
                            {request.comments || 'Ninguno'}
                        </td>
                    </tr>
                    ))}
                    </tbody>
                </table>
            </div>

            <button
                onClick={() => navigate('/employee')}
                className="mt-6 px-4 py-2 bg-gray-700 text-white rounded hover:bg-gray-800"
            >
                Volver al Panel
            </button>
        </div>
    );
};

export default EmployeeVacationStatus;
